insert into public.curated_recipes
  (title,summary,category,source_name,source_url,suitable_for_elimination,servings,preparation_minutes,ingredients,instructions,attribution_note,phase_note,published)
values
('Pasta met tomaat en basilicum','Eenvoudige vegetarische pasta met een kruidige tomatensaus, Parmezaan en verse basilicum.','avondeten','Fodmap Tracker','https://fodmaptracker20.vercel.app',true,2,20,E'180 g low-FODMAP-pasta\n300 g tomatenpassata zonder ui of knoflook\n1 el knoflook-geïnfuseerde olie\n1 tl gedroogde oregano\n10 g verse basilicum\n30 g Parmezaanse kaas, geraspt\n½ tl suiker, optioneel\nZout en zwarte peper',E'1. Kook de pasta volgens de aanwijzingen op de verpakking.\n2. Verwarm ondertussen de knoflookolie in een hapjespan.\n3. Voeg de passata, oregano en eventueel de suiker toe.\n4. Laat de saus 8–10 minuten zachtjes koken.\n5. Scheur de helft van de basilicum en roer deze door de saus.\n6. Giet de pasta af en bewaar ongeveer 50 ml kookwater.\n7. Meng de pasta met de saus. Voeg wat kookwater toe als de saus te dik is.\n8. Verdeel over twee kommen en garneer met Parmezaan en de resterende basilicum.\n\nTip: voeg voor extra eiwitten per persoon een gekookt ei, 100 g kip of een blikje tonijn toe.','Origineel recept, aangeleverd voor en redactioneel verwerkt door Fodmap Tracker.','Gebruik uitsluitend passata zonder ui, knoflook of toegevoegde groenteconcentraten en kies pasta die past binnen je persoonlijke dieetfase.',true),
('Romige citroenpasta met kip en courgette','Frisse, romige pasta met kip, citroen, courgette en lactosevrije kookroom.','avondeten','Fodmap Tracker','https://fodmaptracker20.vercel.app',true,2,25,E'180 g low-FODMAP-pasta\n250 g kipfilet, in reepjes\n120 g courgette, in halve plakjes\n1 el knoflook-geïnfuseerde olie\n100 ml lactosevrije kookroom\n1 biologische citroen\n25 g Parmezaanse kaas\n10 g verse basilicum of peterselie\nZout en zwarte peper',E'1. Rasp het gele deel van de citroenschil en pers een halve citroen uit.\n2. Kook de pasta volgens de verpakking.\n3. Verhit de knoflookolie en bak de kip in 5–6 minuten gaar.\n4. Voeg de courgette toe en bak deze 3 minuten mee.\n5. Zet het vuur laag en voeg de kookroom, citroenrasp en 1 eetlepel citroensap toe.\n6. Giet de pasta af en bewaar wat kookwater.\n7. Meng de pasta en Parmezaan door de saus.\n8. Verdun indien nodig met enkele eetlepels kookwater.\n9. Breng op smaak met peper, zout en eventueel extra citroensap.\n10. Garneer met basilicum of peterselie.','Origineel recept, aangeleverd voor en redactioneel verwerkt door Fodmap Tracker.','Houd de totale hoeveelheid courgette rond 120–130 g voor twee personen en gebruik lactosevrije kookroom.',true),
('Low-FODMAP pasta bolognese','Rijke bolognesesaus met rundvlees, wortel, courgette en het groene deel van bosui.','avondeten','Fodmap Tracker','https://fodmaptracker20.vercel.app',true,2,30,E'180 g low-FODMAP-pasta\n250 g mager rundergehakt\n100 g wortel, fijngesneden\n100 g courgette, fijngesneden\n300 g tomatenpassata zonder ui of knoflook\n1 el tomatenpuree\n1 el knoflook-geïnfuseerde olie\n20 g groen van bosui, in ringetjes\n1 tl oregano\n½ tl gedroogde tijm\n25 g Parmezaanse kaas, optioneel\nZout en zwarte peper',E'1. Kook de pasta volgens de aanwijzingen op de verpakking.\n2. Verwarm de knoflookolie in een ruime pan.\n3. Bak het gehakt rul en lichtbruin.\n4. Voeg de wortel en courgette toe en bak 4 minuten mee.\n5. Voeg de tomatenpuree toe en bak deze 1 minuut.\n6. Voeg de passata, oregano en tijm toe.\n7. Laat de saus 12–15 minuten zachtjes koken.\n8. Roer vlak voor het serveren het groen van de bosui door de saus.\n9. Breng op smaak met zout en peper.\n10. Serveer de saus met de pasta en eventueel Parmezaan.\n\nBewaren: de saus blijft twee dagen goed in de koelkast en kan worden ingevroren.','Origineel recept, aangeleverd voor en redactioneel verwerkt door Fodmap Tracker.','Gebruik alleen het groene deel van de bosui; het witte deel bevat meer fructanen. Controleer passata en tomatenpuree op ui of knoflook.',true),
('Romige pasta met zalm, citroen en dille','Romige vispasta met verse zalm, citroen, dille en lactosevrije room.','avondeten','Fodmap Tracker','https://fodmaptracker20.vercel.app',true,2,25,E'180 g low-FODMAP-pasta\n200 g verse zalmfilet, in blokjes\n100 ml lactosevrije kookroom\n1 el knoflook-geïnfuseerde olie\n1 biologische citroen\n10 g verse dille, fijngehakt\n75 ml low-FODMAP-groente- of kippenbouillon\n1 tl maïzena\nZout en zwarte peper',E'1. Rasp de citroenschil en pers een halve citroen uit.\n2. Kook de pasta volgens de verpakking.\n3. Verwarm de knoflookolie in een koekenpan.\n4. Bak de zalmblokjes ongeveer 3 minuten; ze hoeven nog niet volledig gaar te zijn.\n5. Meng de maïzena met de koude bouillon.\n6. Voeg de bouillon en kookroom toe aan de zalm.\n7. Laat de saus 2–3 minuten zachtjes indikken.\n8. Voeg citroenrasp, 1 eetlepel citroensap en de helft van de dille toe.\n9. Meng de uitgelekte pasta voorzichtig door de saus.\n10. Garneer met de resterende dille en zwarte peper.','Origineel recept, aangeleverd voor en redactioneel verwerkt door Fodmap Tracker.','Controleer bouillon zorgvuldig; ui en knoflook zijn veelvoorkomende ingrediënten. Gebruik lactosevrije kookroom.',true),
('Verse basilicumpesto-pasta','Vegetarische pasta met zelfgemaakte basilicumpesto, pijnboompitten en cherrytomaten.','avondeten','Fodmap Tracker','https://fodmaptracker20.vercel.app',true,2,20,E'180 g low-FODMAP-pasta\n30 g verse basilicumblaadjes\n25 g pijnboompitten\n35 g Parmezaanse kaas, geraspt\n3 el olijfolie\n1 el knoflook-geïnfuseerde olie\n1 el citroensap\n100 g cherrytomaten, gehalveerd\nZout en zwarte peper',E'1. Rooster de pijnboompitten kort in een droge koekenpan.\n2. Kook de pasta volgens de verpakking.\n3. Doe basilicum, pijnboompitten, Parmezaan, olijfolie, knoflookolie en citroensap in een blender of hoge beker.\n4. Pureer tot een grove pesto. Voeg eventueel 1–2 eetlepels pastawater toe.\n5. Giet de pasta af en bewaar 75 ml kookwater.\n6. Doe de pasta terug in de pan, maar zet deze niet meer op hoog vuur.\n7. Meng de pesto en cherrytomaten door de pasta.\n8. Voeg voldoende kookwater toe om een gladde saus te maken.\n9. Breng op smaak met peper en eventueel een beetje zout.\n\nBewaren: zelfgemaakte pesto blijft afgedekt één dag goed in de koelkast.','Origineel recept, aangeleverd voor en redactioneel verwerkt door Fodmap Tracker.','Verdeel het gerecht in twee porties en gebruik knoflook-geïnfuseerde olie zonder stukjes knoflook.',true),
('Aziatische kip-ananaspasta','Zoet-frisse roerbakpasta met kip, ananas, groenten, gember en sesam.','avondeten','Fodmap Tracker','https://fodmaptracker20.vercel.app',true,2,25,E'180 g low-FODMAP-spaghetti of rijstnoedels\n250 g kipfilet, in blokjes\n120 g verse ananas, in kleine stukjes\n100 g groene paprika, in reepjes\n80 g wortel, in dunne reepjes\n20 g groen van bosui\n1 el knoflook-geïnfuseerde olie\n1 tl sesamolie\n2 el glutenvrije sojasaus of tamari\n1 el limoensap\n1 tl verse gember, geraspt\n1 tl ahornsiroop, optioneel\n1 tl sesamzaad',E'1. Meng de sojasaus, limoensap, gember, sesamolie en eventueel ahornsiroop.\n2. Kook de pasta of noedels volgens de verpakking.\n3. Verhit de knoflookolie in een wok.\n4. Bak de kip in 5–6 minuten gaar en goudbruin.\n5. Voeg paprika en wortel toe en roerbak 3 minuten.\n6. Voeg de ananas toe en bak deze 1 minuut mee.\n7. Voeg de uitgelekte pasta en de dressing toe.\n8. Schep alles 1–2 minuten om totdat de saus goed verdeeld is.\n9. Garneer met het groen van de bosui en sesamzaad.','Origineel recept, aangeleverd voor en redactioneel verwerkt door Fodmap Tracker.','Gebruik verse ananas of ananas op sap die goed is uitgelekt. Vermijd ananas op appelsap of siroop met fructose en gebruik alleen het groene deel van bosui.',true),
('Klassieke carbonara zonder room','Klassieke romige carbonara met ei, Parmezaan en gecontroleerde spekreepjes, zonder room.','avondeten','Fodmap Tracker','https://fodmaptracker20.vercel.app',true,2,20,E'180 g low-FODMAP-spaghetti\n100 g spekreepjes zonder ui of knoflook\n2 eieren\n1 extra eidooier\n50 g Parmezaanse kaas, fijn geraspt\n1 tl knoflook-geïnfuseerde olie\nRuim zwarte peper\nEventueel een klein beetje zout',E'1. Klop de eieren en eidooier los met de Parmezaanse kaas en zwarte peper.\n2. Kook de spaghetti volgens de verpakking.\n3. Bak ondertussen de spekreepjes in de knoflookolie krokant.\n4. Bewaar circa 100 ml pastawater en giet de spaghetti af.\n5. Voeg de spaghetti toe aan het spek en zet het vuur uit.\n6. Laat de pan ongeveer 30 seconden afkoelen.\n7. Voeg het eimengsel toe en schep onmiddellijk krachtig om.\n8. Voeg beetje voor beetje pastawater toe totdat een romige saus ontstaat.\n9. Serveer direct met extra zwarte peper.\n\nVoedselveiligheid: gebruik verse eieren en zorg dat de pasta nog goed heet is wanneer het eimengsel wordt toegevoegd.','Origineel recept, aangeleverd voor en redactioneel verwerkt door Fodmap Tracker.','Controleer spek en vleeswaren op knoflookpoeder, uienpoeder en honing. Kies spaghetti die past binnen je persoonlijke dieetfase.',true),
('Mediterrane tonijn-tomatenpasta','Snelle mediterrane pasta met tonijn, tomaat, olijven, kappertjes en citroen.','avondeten','Fodmap Tracker','https://fodmaptracker20.vercel.app',true,2,20,E'180 g low-FODMAP-pasta\n1 blik tonijn, circa 145 g uitgelekt\n300 g tomatenpassata zonder ui of knoflook\n1 el knoflook-geïnfuseerde olie\n30 g zwarte of groene olijven, in ringetjes\n1 el kappertjes, afgespoeld\n1 tl oregano\n10 g verse basilicum of peterselie\n½ citroen\nZwarte peper en eventueel zout',E'1. Kook de pasta volgens de verpakking.\n2. Verwarm de knoflookolie in een hapjespan.\n3. Voeg de passata en oregano toe en laat 7 minuten zachtjes koken.\n4. Voeg de tonijn, olijven en kappertjes toe.\n5. Verwarm de saus nog 2–3 minuten. Roer voorzichtig zodat de tonijn enigszins heel blijft.\n6. Voeg 1 eetlepel citroensap toe.\n7. Meng de uitgelekte pasta door de saus.\n8. Garneer met basilicum of peterselie en zwarte peper.\n\nTip: proef het gerecht voordat je zout toevoegt; olijven, kappertjes en tonijn zijn al zout.','Origineel recept, aangeleverd voor en redactioneel verwerkt door Fodmap Tracker.','Gebruik passata zonder ui, knoflook of toegevoegde groenteconcentraten en controleer gekruide olijven en kappertjes.',true),
('Pasta met geroosterde groenten en feta','Vegetarische ovenpasta met aubergine, paprika, wortel, tomaat en feta.','avondeten','Fodmap Tracker','https://fodmaptracker20.vercel.app',true,2,35,E'180 g low-FODMAP-pasta\n120 g aubergine, in blokjes\n100 g groene paprika, in stukken\n100 g wortel, in dunne plakjes\n100 g cherrytomaten\n1½ el olijfolie\n1 tl oregano\n80 g feta\n1 el citroensap\n10 g verse peterselie\nZout en zwarte peper',E'1. Verwarm de oven voor op 210 °C.\n2. Verdeel aubergine, paprika, wortel en tomaten over een bakplaat.\n3. Meng de groenten met de olijfolie, oregano, peper en een beetje zout.\n4. Rooster de groenten 20–25 minuten en schep ze halverwege om.\n5. Kook ondertussen de pasta volgens de verpakking.\n6. Bewaar 50 ml kookwater en giet de pasta af.\n7. Meng de pasta met de geroosterde groenten, citroensap en het kookwater.\n8. Verkruimel de feta over het gerecht.\n9. Garneer met peterselie en zwarte peper.','Origineel recept, aangeleverd voor en redactioneel verwerkt door Fodmap Tracker.','De hoeveelheden groenten zijn verdeeld over twee porties. Voeg niet zonder portiecontrole grote extra hoeveelheden courgette, zoete aardappel of paddenstoelen toe.',true),
('Romige pompoen-saliepasta','Vegetarische pasta met geroosterde kabocha, wortel, lactosevrije room en krokante salie.','avondeten','Fodmap Tracker','https://fodmaptracker20.vercel.app',true,2,35,E'180 g low-FODMAP-pasta\n150 g kabocha- of Japanse pompoen, in blokjes\n100 g wortel, in plakjes\n1 el knoflook-geïnfuseerde olie\n100 ml lactosevrije kookroom\n75 ml water of low-FODMAP-groentebouillon\n6 verse salieblaadjes\n30 g Parmezaanse kaas\n1 tl citroensap\nSnufje nootmuskaat\nZout en zwarte peper',E'1. Verwarm de oven voor op 210 °C.\n2. Meng de pompoen en wortel met de helft van de knoflookolie.\n3. Rooster de groenten 20–25 minuten totdat ze zacht zijn.\n4. Kook ondertussen de pasta volgens de verpakking.\n5. Bak de salieblaadjes kort in de resterende olie en haal ze daarna uit de pan.\n6. Pureer de geroosterde groenten met de kookroom en bouillon of het water.\n7. Verwarm de saus op laag vuur.\n8. Voeg Parmezaan, citroensap en nootmuskaat toe.\n9. Meng de pasta door de saus en verdun indien nodig met pastawater.\n10. Garneer met de krokante salie en zwarte peper.','Origineel recept, aangeleverd voor en redactioneel verwerkt door Fodmap Tracker.','Gebruik specifiek kabocha of Japanse pompoen. Porties verschillen sterk per pompoensoort; flespompoen is niet één-op-één uitwisselbaar. Controleer bouillon op ui en knoflook.',true)
